-- C-04: payment request lifecycle and all Workflow/budget entry paths.
set local lock_timeout='5s';set local statement_timeout='60s';
create schema payment_request_private;
revoke all on schema payment_request_private from public,anon,authenticated,service_role;
grant usage on schema payment_request_private to authenticated;
create function payment_request_private.allowed(a text) returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin
 perform asset_posting_private.identity();return asset_posting_private.allowed('treasury:payment-requests',a) or asset_posting_private.allowed('accounting:payment-requests',a);exception when insufficient_privilege then return false;end$$;
create function payment_request_private.access(a text) returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=asset_posting_private.identity();begin if not payment_request_private.allowed(a) then raise exception using errcode='42501',message='El rol activo no puede realizar esta acción en Solicitudes de Pago.';end if;return sid;end$$;
create function payment_request_private.context() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare v boolean;c boolean;e boolean;d boolean;begin perform asset_posting_private.identity();v:=payment_request_private.allowed('view');c:=payment_request_private.allowed('create');e:=payment_request_private.allowed('edit');d:=payment_request_private.allowed('delete');if not(v or c or e) then raise exception using errcode='42501',message='Sin acceso a Solicitudes de Pago.';end if;return jsonb_build_object('canView',v,'canCreate',c,'canEdit',e,'canDelete',d);end$$;
create or replace function public.pr_access() returns bigint language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select asset_posting_private.identity()$$;
-- Preserve originals; all mutations below call them only through guarded entry points.
do $$declare f regprocedure;body text;n text;begin
 for f in select p.oid::regprocedure from pg_proc p where p.pronamespace='public'::regnamespace and p.proname=any(array['pr_options','pr_invoices','pr_report','pr_detail','pr_save','pr_save_without_budget','pr_submit','pr_transition','pr_execute','pr_execute_without_payment_batch_guard','pr_execute_without_budget','pr_supports','pr_support_save','pr_support_delete','pr_validate','pr_invoice_balance','pr_allowed_account','pr_resolve_payment_request_approver','pr_payment_request_admin_route','pr_resolve_up_approver','payment_request_report_options','run_payment_request_report','wf_start_entity_without_budget','wf_apply_entity_status_without_budget','wf_apply_entity_status','wf_entity_data_without_budget','wf_entity_data','wf_act','wf_instance_detail','wf_notify_level'])loop execute format('alter function %s set schema payment_request_private',f);end loop;
 for f in select p.oid::regprocedure from pg_proc p where p.pronamespace='payment_request_private'::regnamespace and p.proname not in('allowed','access','context')loop
  execute format('alter function %s set search_path=pg_catalog,public,pg_temp',f);body:=pg_get_functiondef(f);
  foreach n in array array['pr_save_without_budget','pr_execute_without_payment_batch_guard','pr_execute_without_budget','pr_supports','pr_invoice_balance','pr_allowed_account','pr_resolve_payment_request_approver','pr_payment_request_admin_route','pr_resolve_up_approver','wf_apply_entity_status_without_budget','wf_apply_entity_status','wf_entity_data_without_budget','wf_entity_data','wf_notify_level']loop
   body:=replace(body,'public.'||n||'(','payment_request_private.'||n||'(');body:=regexp_replace(body,'(?<![a-zA-Z0-9_.])'||n||'\(','payment_request_private.'||n||'(','g');
  end loop;execute body;
 end loop;
end$$;
create function payment_request_private.visible(rid bigint) returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin return payment_request_private.allowed('view') and exists(select 1 from public.solicitudes_pago where id=rid and id_subsidiaria=asset_posting_private.identity());end$$;
create function payment_request_private.header(rid bigint,lock_row boolean default false) returns public.solicitudes_pago language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare h public.solicitudes_pago;sid bigint:=asset_posting_private.identity();begin
 if lock_row then select * into h from public.solicitudes_pago where id=rid and id_subsidiaria=sid for update;else select * into h from public.solicitudes_pago where id=rid and id_subsidiaria=sid;end if;
 if not found then raise exception using errcode='42501',message='Solicitud no disponible en la subsidiaria activa.';end if;return h;end$$;
create function payment_request_private.editable(h public.solicitudes_pago) returns void language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin
 if h.estado not in('BORRADOR','RECHAZADO') or (h.id_solicitante is distinct from public.app_user_id() and not public.app_is_admin()) or h.payment_id is not null or h.check_id is not null or h.journal_id is not null or h.payment_batch_id is not null or h.batch_processing_status='LOCKED_IN_BATCH' then raise exception using errcode='55000',message='La solicitud conserva propietario, estado e historial de pagos o lotes.';end if;end$$;
create function payment_request_private.save_access(p jsonb) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare h public.solicitudes_pago;rid bigint:=nullif(p->>'id','')::bigint;begin
 perform payment_request_private.access(case when rid is null then 'create' else 'edit' end);
 if rid is not null then h:=payment_request_private.header(rid,true);perform payment_request_private.editable(h);if h.version is distinct from (p->>'version')::integer then raise exception using errcode='55000',message='La versión cambió; vuelva a abrir la solicitud.';end if;end if;end$$;
create function payment_request_private.prepare(p jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare line jsonb;amount numeric;total numeric:=0;begin
 perform payment_request_private.save_access(p);
 if p is null or jsonb_typeof(p)<>'object' or p->>'type' is null or p->>'type' not in('CXP','OTROS') or jsonb_typeof(p->'lines') is distinct from 'array' or jsonb_array_length(p->'lines') not between 1 and 500 then raise exception using errcode='22023',message='Indique tipo y entre 1 y 500 líneas.';end if;
 if p ?| array['estado','status','id_subsidiaria','subsidiaryId','id_solicitante','assigned_approver_id','approverId','approvalRoute','payment_id','check_id','journal_id','payment_batch_id'] then raise exception using errcode='42501',message='No puede sustituir propietario, aprobación ni origen de la solicitud.';end if;
 if nullif(trim(p->>'concept'),'') is null or nullif(p->>'plannedDate','') is null or not isfinite((p->>'plannedDate')::date) then raise exception using errcode='22023',message='Indique concepto y fecha programada válida.';end if;
 for line in select value from jsonb_array_elements(p->'lines')loop
  amount:=(line->>'amount')::numeric;if jsonb_typeof(line)<>'object' or not asset_posting_private.finite(amount) or amount<=0 then raise exception using errcode='22023',message='Cada importe debe ser positivo y finito.';end if;total:=total+amount;
  if p->>'type'='OTROS' and (line->>'entityType' is null or line->>'entityType' not in('Cliente','Proveedor','Empleado','Agencia Tributaria')) then raise exception using errcode='22023',message='Seleccione un tipo de tercero válido.';end if;
 end loop;if total>1000000000000 then raise exception using errcode='22023',message='Importe fuera del límite permitido.';end if;
 if p->>'type'='CXP' then
  if (select count(*)<>count(distinct (x->>'invoiceId')::bigint) from jsonb_array_elements(p->'lines')x) then raise exception using errcode='22023',message='No repita facturas.';end if;
  return p||jsonb_build_object('lines',(select jsonb_agg(x order by (x->>'invoiceId')::bigint)from jsonb_array_elements(p->'lines')x));
 end if;return p;end$$;
create function payment_request_private.validate_extra(rid bigint) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare h public.solicitudes_pago:=payment_request_private.header(rid);l public.solicitudes_pago_lineas;total numeric:=0;n integer:=0;begin
 if h.tipo_solicitud not in('CXP','OTROS') or not asset_posting_private.finite(h.total) or h.total<=0 or h.total>1000000000000 then raise exception using errcode='22023',message='Encabezado de solicitud inválido.';end if;
 for l in select * from public.solicitudes_pago_lineas where id_solicitud=rid order by id_factura_proveedor,id loop
  n:=n+1;if not asset_posting_private.finite(l.monto) or l.monto<=0 then raise exception using errcode='22023',message='Las líneas requieren importes positivos y finitos.';end if;total:=total+l.monto;
  if h.tipo_solicitud='CXP' then
   if not exists(select 1 from public.supplier_invoice i where i.invoice_id=l.id_factura_proveedor and i.subsidiary_id=h.id_subsidiaria and i.supplier_id=h.id_proveedor and i.currency_id=h.id_moneda) then raise exception using errcode='42501',message='Factura ajena al proveedor, moneda o subsidiaria.';end if;
  else
   if l.tipo_tercero is null or l.tipo_tercero not in('Cliente','Proveedor','Empleado','Agencia Tributaria') then raise exception using errcode='22023',message='Tercero inválido.';end if;
   perform asset_posting_private.account(l.id_cuenta_contable);
   if l.id_proveedor is not null and exists(select 1 from public.suppliers where supplier_id=l.id_proveedor and is_inactive) or l.id_cliente is not null and exists(select 1 from public.customers where customer_id=l.id_cliente and is_inactive) then raise exception using errcode='42501',message='El tercero está inactivo.';end if;
  end if;
 end loop;
 if n not between 1 and 500 or total<>h.total or (h.tipo_solicitud='CXP' and exists(select 1 from public.solicitudes_pago_lineas where id_solicitud=rid group by id_factura_proveedor having count(*)>1)) then raise exception using errcode='22023',message='Líneas o total de solicitud inconsistentes.';end if;
 if h.tipo_solicitud='CXP' and exists(select 1 from public.suppliers where supplier_id=h.id_proveedor and is_inactive) then raise exception using errcode='42501',message='Proveedor inactivo.';end if;
end$$;
-- Internal compatibility entry for the batch builder and existing engines.
create function public.pr_validate(p_id bigint) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin perform payment_request_private.validate_extra(p_id);perform payment_request_private.pr_validate(p_id);end$$;
create function payment_request_private.approval_eligible(h public.solicitudes_pago) returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$
 select payment_request_private.allowed('view') and h.estado='PENDIENTE_APROBACION' and exists(select 1 from public.wf_instances i join public.wf_instance_steps s on s.instance_id=i.id and s.nivel=i.current_level where i.entity_type='PAYMENT_REQUEST' and i.entity_id=h.id and i.subsidiaria_id=h.id_subsidiaria and i.status='EN_REVISION' and s.status='PENDIENTE' and (s.usuario_aprobador_id=public.app_user_id() or s.rol_aprobador_id=public.app_active_role_id() or public.app_is_admin()) and not exists(select 1 from public.wf_step_decisions d where d.step_id=s.id and d.usuario_id=public.app_user_id()))
$$;
create function payment_request_private.submit_access(rid bigint,version integer) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare h public.solicitudes_pago;begin perform payment_request_private.access('edit');h:=payment_request_private.header(rid,true);perform payment_request_private.editable(h);if h.version is distinct from version then raise exception using errcode='55000',message='La solicitud cambió; vuelva a abrirla.';end if;perform public.pr_validate(rid);end$$;
create function payment_request_private.transition_access(p jsonb) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare h public.solicitudes_pago;a text:=upper(p->>'transition');begin
 if a='SUBMIT' then perform payment_request_private.submit_access((p->>'id')::bigint,(p->>'version')::integer);return;end if;
 if a is null or a not in('APPROVE','REJECT','CANCEL') then raise exception using errcode='22023',message='Transición inválida.';end if;
 perform payment_request_private.access(case when a='CANCEL' then 'delete' else 'view' end);
 perform 1 from public.wf_instances where entity_type='PAYMENT_REQUEST' and entity_id=(p->>'id')::bigint for update;
 h:=payment_request_private.header((p->>'id')::bigint,true);
 if h.version is distinct from (p->>'version')::integer or h.estado in('APLICADO','ANULADO') or h.payment_id is not null or h.check_id is not null or h.journal_id is not null or h.payment_batch_id is not null or h.batch_processing_status='LOCKED_IN_BATCH' then raise exception using errcode='55000',message='La versión, estado o lote protege esta solicitud.';end if;
 if a in('APPROVE','REJECT') and not payment_request_private.approval_eligible(h) then raise exception using errcode='42501',message='El rol activo no es el aprobador pendiente.';end if;
 if a='CANCEL' and h.id_solicitante is distinct from public.app_user_id() and not public.app_is_admin() then raise exception using errcode='42501',message='Solo el solicitante o administrador puede anular.';end if;
 if a in('REJECT','CANCEL') and nullif(trim(p->>'reason'),'') is null then raise exception using errcode='22023',message='Indique el motivo.';end if;
 if a='APPROVE' then perform public.pr_validate(h.id);end if;end$$;
create function payment_request_private.batch_executor(h public.solicitudes_pago,p jsonb) returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare bid text:=nullif(current_setting('nexo.payment_batch_id',true),'');begin
 return bid is not null and bid~'^[0-9]+$' and h.payment_batch_id::text=bid and h.batch_processing_status='LOCKED_IN_BATCH' and public.payment_batch_has_permission('TREASURY_PAYMENT_BATCH_EXECUTE') and exists(select 1 from public.payment_batches b join public.payment_batch_items i using(batch_id) where b.batch_id=bid::bigint and b.subsidiary_id=asset_posting_private.identity() and b.status in('FILE_GENERATED','SENT_TO_BANK','PARTIALLY_REJECTED') and i.payment_request_id=h.id and i.supplier_id=h.id_proveedor and i.currency_id=h.id_moneda and i.processing_status='LOCKED_IN_BATCH' and i.application_amount=h.total and b.currency_id=h.id_moneda and b.bank_account_id=(p->>'bankId')::bigint and b.execution_date=(p->>'date')::date and b.exchange_rate=(p->>'rate')::numeric);
end$$;
create function payment_request_private.execute_access(p jsonb) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare h public.solicitudes_pago;begin
 h:=payment_request_private.header((p->>'id')::bigint,true);
 if not payment_request_private.batch_executor(h,p) then perform payment_request_private.access('edit');end if;
 if not public.pr_can_execute() then raise exception using errcode='42501',message='La ejecución requiere Tesorería o un ejecutor de lote autorizado.';end if;
 if h.estado='APLICADO' then return;end if;
 if h.estado<>'APROBADO' or h.version is distinct from (p->>'version')::integer or (h.batch_processing_status='LOCKED_IN_BATCH' and not payment_request_private.batch_executor(h,p)) or h.payment_id is not null or h.check_id is not null or h.journal_id is not null then raise exception using errcode='55000',message='La solicitud no está aprobada, actualizada y libre para esta ejecución.';end if;
end$$;
create function payment_request_private.execute_engine(p jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare h public.solicitudes_pago;b public.bank_account;rate numeric;result jsonb;d numeric;c numeric;begin
 perform payment_request_private.execute_access(p);h:=payment_request_private.header((p->>'id')::bigint,true);if h.estado='APLICADO' then return jsonb_build_object('id',h.id,'journalId',h.journal_id);end if;
 perform public.pr_validate(h.id);rate:=(p->>'rate')::numeric;
 if not asset_posting_private.finite(rate) or rate<=0 or rate>1000000000 or (h.id_moneda=(select currency_id from public.subsidiaries where subsidiary_id=h.id_subsidiaria) and rate<>1) then raise exception using errcode='22023',message='Tipo de cambio inválido.';end if;
 select * into b from public.bank_account where bank_account_id=(p->>'bankId')::bigint and subsidiary_id=h.id_subsidiaria and currency_id=h.id_moneda and not coalesce(is_credit_card,false) for update;
 if not found then raise exception using errcode='42501',message='Banco o moneda no disponible.';end if;perform asset_posting_private.account(b.account_id);
 if not asset_posting_private.finite(b.balance) then raise exception using errcode='55000',message='Saldo bancario inválido.';end if;
 perform supplier_payment_private.bank_window(b.bank_account_id,(p->>'date')::date);
 perform 1 from public.fiscal_periods where subsidiary_id=h.id_subsidiaria and (p->>'date')::date between start_date and end_date and not is_closed and not coalesce(gl_closed,false) and not coalesce(is_inactive,false) and(h.tipo_solicitud<>'CXP' or not coalesce(ap_closed,false)) for share;if not found then raise exception using errcode='55000',message='No hay período GL/AP abierto para ejecutar.';end if;
 result:=payment_request_private.pr_execute_without_budget(p);h:=payment_request_private.header(h.id);
 select coalesce(sum(debit),0),coalesce(sum(credit),0) into d,c from public.journal_line where journal_id=h.journal_id;
 if h.estado<>'APLICADO' or h.journal_id is null or not asset_posting_private.finite(d) or not asset_posting_private.finite(c) or d<=0 or abs(d-c)>.000001 then raise exception using errcode='55000',message='La ejecución no produjo un asiento consistente.';end if;
 select coalesce(sum(debit_amount),0),coalesce(sum(credit_amount),0) into d,c from public.gl_impact where transaction_id=(select transaction_id from public.journal where journal_id=h.journal_id);
 if not asset_posting_private.finite(d) or not asset_posting_private.finite(c) or d<=0 or abs(d-c)>.000001 then raise exception using errcode='55000',message='El mayor de la ejecución no está balanceado.';end if;
 return result;end$$;
-- Guard the dispatcher itself; payload/fingerprint of budget overrides stay original.
do $$declare body text;modified text;begin body:=pg_get_functiondef('public.budget_run(text,jsonb,bigint)'::regprocedure);
 modified:=replace(body,'declare invoice_payload jsonb;','declare request_payload jsonb;invoice_payload jsonb;');
 modified:=replace(modified,'begin'||chr(10),'begin'||chr(10)||' if p_type in(''SOL_PAG'',''SOL_PAG_EXECUTE'') and p_id is distinct from nullif(p_payload->>''id'','''')::bigint then raise exception using errcode=''42501'',message=''El identificador presupuestario debe coincidir con la solicitud.'';end if; if p_type=''SOL_PAG'' then perform payment_request_private.save_access(p_payload);elsif p_type=''SOL_PAG_EXECUTE'' then perform payment_request_private.execute_access(p_payload);elsif p_type=''WORKFLOW_START'' and p_payload->>''entityType''=''PAYMENT_REQUEST'' then perform payment_request_private.submit_access(p_id,(p_payload#>>''{context,requestVersion}'')::integer);end if;'||chr(10));
 modified:=replace(modified,'before_state:=budget_state(sid);','if p_type=''SOL_PAG'' then request_payload:=payment_request_private.prepare(p_payload);end if;before_state:=budget_state(sid);');
 modified:=regexp_replace(modified,'(?<![a-zA-Z0-9_.])(?:public\.)?pr_save_without_budget\(p_payload\)','payment_request_private.pr_save_without_budget(request_payload)','g');
 modified:=regexp_replace(modified,'(?<![a-zA-Z0-9_.])(?:public\.)?pr_execute_without_budget\(p_payload\)','payment_request_private.execute_engine(p_payload)','g');
 modified:=replace(modified,'result:=wf_start_entity_without_budget(p_payload->>''entityType'',p_id,coalesce(p_payload->''context'',''{}''));','if p_payload->>''entityType''=''PAYMENT_REQUEST'' then result:=payment_request_private.wf_start_entity_without_budget(''PAYMENT_REQUEST'',p_id,jsonb_build_object(''requestVersion'',(select version from public.solicitudes_pago where id=p_id)));else result:=wf_start_entity_without_budget(p_payload->>''entityType'',p_id,coalesce(p_payload->''context'',''{}''));end if;');
 if modified=body or position('request_payload jsonb' in modified)=0 or position('payment_request_private.execute_engine(p_payload)' in modified)=0 or position('payment_request_private.wf_start_entity_without_budget(' in modified)=0 then raise exception 'Unexpected request budget dispatcher';end if;execute modified;
end$$;
create function public.pr_access_context() returns jsonb language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select payment_request_private.context()$$;
create function public.pr_options() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare ctx jsonb:=payment_request_private.context();begin return payment_request_private.pr_options()||jsonb_build_object('permissions',ctx,'canExecute',(ctx->>'canEdit')::boolean and public.pr_can_execute());end$$;
create function public.pr_report(p jsonb) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform payment_request_private.access('view');return payment_request_private.pr_report(p);end$$;
create function public.pr_invoices(p jsonb) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform payment_request_private.context();if nullif(p->>'requestId','') is not null then perform payment_request_private.header((p->>'requestId')::bigint);end if;return payment_request_private.pr_invoices(p);end$$;
create function public.pr_detail(p jsonb) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare h public.solicitudes_pago;own boolean;mutable boolean;ap boolean;begin perform payment_request_private.access('view');select * into h from public.solicitudes_pago where id=(p->>'id')::bigint and id_subsidiaria=asset_posting_private.identity();if not found then raise exception using errcode='42501',message='Solicitud no disponible.';end if;
 own:=h.id_solicitante=public.app_user_id() or public.app_is_admin();mutable:=h.estado in('BORRADOR','RECHAZADO') and h.payment_id is null and h.check_id is null and h.journal_id is null and h.payment_batch_id is null and coalesce(h.batch_processing_status,'')<>'LOCKED_IN_BATCH';ap:=payment_request_private.approval_eligible(h);
 return payment_request_private.pr_detail(p)||jsonb_build_object('canActApproval',ap,'actions',jsonb_build_object('canEdit',mutable and own and payment_request_private.allowed('edit'),'canSubmit',mutable and own and payment_request_private.allowed('edit'),'canApprove',ap,'canCancel',own and payment_request_private.allowed('delete') and h.estado not in('APLICADO','ANULADO') and h.payment_batch_id is null,'canExecute',h.estado='APROBADO' and payment_request_private.allowed('edit') and public.pr_can_execute() and coalesce(h.batch_processing_status,'')<>'LOCKED_IN_BATCH'));end$$;
create function public.pr_save(p jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin perform payment_request_private.save_access(p);return public.budget_run('SOL_PAG',p,nullif(p->>'id','')::bigint);end$$;
create function public.pr_submit(p jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin perform payment_request_private.submit_access((p->>'id')::bigint,(p->>'version')::integer);return payment_request_private.pr_submit(p);end$$;
create function public.pr_transition(p jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin perform payment_request_private.transition_access(p);return payment_request_private.pr_transition(p);end$$;
create function public.pr_execute(p jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin perform payment_request_private.execute_access(p);return payment_request_private.pr_execute(p);end$$;
create function public.pr_supports(p jsonb) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform payment_request_private.access('view');if not payment_request_private.visible((p->>'id')::bigint) then raise exception using errcode='42501',message='Solicitud no disponible.';end if;return payment_request_private.pr_supports(p);end$$;
create function payment_request_private.support_access(p jsonb) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare h public.solicitudes_pago;begin perform asset_posting_private.identity();if not(payment_request_private.allowed('edit') or payment_request_private.allowed('create')) then raise exception using errcode='42501',message='Sin permiso para respaldos de solicitudes.';end if;h:=payment_request_private.header((p->>'id')::bigint,true);perform payment_request_private.editable(h);end$$;
create function public.pr_support_save(p jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare bytes integer;begin perform payment_request_private.support_access(p);
 if p->>'type'='Archivo' then
  if length(p->>'fileData')>7000000 or coalesce(p->>'fileData','')!~'^data:[A-Za-z0-9.+/_-]+;base64,[A-Za-z0-9+/=[:space:]]+$' then raise exception using errcode='22023',message='Contenido de archivo inválido o excesivo.';end if;
  bytes:=octet_length(decode(split_part(p->>'fileData',',',2),'base64'));if bytes not between 1 and 5242880 or bytes is distinct from (p->>'fileSize')::integer then raise exception using errcode='22023',message='El tamaño real del archivo no coincide o supera 5 MB.';end if;
 end if;return payment_request_private.pr_support_save(p);end$$;
create function public.pr_support_delete(p jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin perform payment_request_private.support_access(p);return payment_request_private.pr_support_delete(p);end$$;
-- Shared Workflow APIs keep their other document paths; request status writers are internal only.
create function public.wf_act(p_instance_id bigint,p_action text,p_comment text default null,p_ip inet default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare i public.wf_instances;h public.solicitudes_pago;a text:=upper(p_action);begin
 perform asset_posting_private.identity();select * into i from public.wf_instances where id=p_instance_id for update;
 if i.entity_type='PAYMENT_REQUEST' then h:=payment_request_private.header(i.entity_id,true);
  perform payment_request_private.transition_access(jsonb_build_object('id',h.id,'version',h.version,'transition',case a when 'APROBAR' then 'APPROVE' when 'RECHAZAR' then 'REJECT' when 'CANCELAR' then 'CANCEL' else a end,'reason',p_comment));
  if i.subsidiaria_id<>h.id_subsidiaria or i.status='CANCELADO' then raise exception using errcode='55000',message='Instancia de aprobación protegida.';end if;
 end if;return payment_request_private.wf_act(p_instance_id,p_action,p_comment,p_ip);end$$;
create function public.wf_start_entity_without_budget(p_entity_type text,p_entity_id bigint,p_context jsonb default '{}') returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_entity_type='PAYMENT_REQUEST' then raise exception using errcode='42501',message='Use Enviar a aprobación con control presupuestario.';end if;return payment_request_private.wf_start_entity_without_budget(p_entity_type,p_entity_id,p_context);end$$;
create function public.wf_apply_entity_status_without_budget(p_type text,p_id bigint,p_status text) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_type='PAYMENT_REQUEST' then raise exception using errcode='42501',message='El estado requiere una decisión del flujo.';end if;perform payment_request_private.wf_apply_entity_status_without_budget(p_type,p_id,p_status);end$$;
create function public.wf_apply_entity_status(p_type text,p_id bigint,p_status text) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_type='PAYMENT_REQUEST' then raise exception using errcode='42501',message='El estado requiere una decisión del flujo.';end if;perform payment_request_private.wf_apply_entity_status(p_type,p_id,p_status);end$$;
create function public.wf_entity_data_without_budget(p_type text,p_id bigint) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_type='PAYMENT_REQUEST' then perform payment_request_private.access('view');if not payment_request_private.visible(p_id) then raise exception using errcode='42501',message='Solicitud no disponible.';end if;end if;return payment_request_private.wf_entity_data_without_budget(p_type,p_id);end$$;
create function public.wf_entity_data(p_type text,p_id bigint) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_type='PAYMENT_REQUEST' then return public.wf_entity_data_without_budget(p_type,p_id);end if;return payment_request_private.wf_entity_data(p_type,p_id);end$$;
create function public.wf_notify_level(p_instance_id bigint) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if exists(select 1 from public.wf_instances where id=p_instance_id and entity_type='PAYMENT_REQUEST') then raise exception using errcode='42501',message='La notificaci?n se genera dentro del flujo autorizado.';end if;perform payment_request_private.wf_notify_level(p_instance_id);end$$;
create function public.wf_instance_detail(p_entity_type text,p_entity_id bigint) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_entity_type='PAYMENT_REQUEST' then perform payment_request_private.access('view');if not payment_request_private.visible(p_entity_id) then raise exception using errcode='42501',message='Solicitud no disponible.';end if;end if;return payment_request_private.wf_instance_detail(p_entity_type,p_entity_id);end$$;
do $$declare body text;begin body:=pg_get_functiondef('public.wf_inbox()'::regprocedure);if position('where i.subsidiaria_id=' in body)=0 then raise exception 'Unexpected Workflow inbox';end if;execute replace(body,'where i.subsidiaria_id=','where (i.entity_type<>''PAYMENT_REQUEST'' or (payment_request_private.visible(i.entity_id) and (s.usuario_aprobador_id=public.app_user_id() or s.rol_aprobador_id=public.app_active_role_id() or public.app_is_admin()))) and i.subsidiaria_id=');end$$;
create function public.payment_request_report_options() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform asset_posting_private.access('reports:accounting-reports','view');return payment_request_private.payment_request_report_options();end$$;
create function public.run_payment_request_report(p_filters jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform asset_posting_private.access('reports:accounting-reports','view');return payment_request_private.run_payment_request_report(p_filters);end$$;
do $$declare t text;p record;c record;begin foreach t in array array['solicitudes_pago','solicitudes_pago_lineas','solicitudes_pago_eventos','solicitudes_pago_respaldos']loop
 execute format('alter table public.%I enable row level security',t);for p in select policyname from pg_policies where schemaname='public' and tablename=t loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 for c in select column_name from information_schema.columns where table_schema='public' and table_name=t loop execute format('revoke all (%I) on public.%I from public,anon,authenticated,service_role',c.column_name,t);end loop;execute format('grant select on public.%I to authenticated',t);
 execute format('create policy payment_request_read on public.%I for select to authenticated using(payment_request_private.visible(%I))',t,case when t='solicitudes_pago' then 'id' else 'id_solicitud' end);
end loop;end$$;
revoke all on all functions in schema payment_request_private from public,anon,authenticated,service_role;
grant execute on function payment_request_private.visible(bigint) to authenticated;
revoke all on function public.pr_validate(bigint),public.pr_access(),public.pr_can_approve(),public.pr_can_execute(),public.pr_sync_dynamic_current_approver() from public,anon,authenticated,service_role;
revoke all on function public.pr_access_context(),public.pr_options(),public.pr_invoices(jsonb),public.pr_report(jsonb),public.pr_detail(jsonb),public.pr_save(jsonb),public.pr_submit(jsonb),public.pr_transition(jsonb),public.pr_execute(jsonb),public.pr_supports(jsonb),public.pr_support_save(jsonb),public.pr_support_delete(jsonb),public.payment_request_report_options(),public.run_payment_request_report(jsonb),public.wf_act(bigint,text,text,inet),public.wf_start_entity_without_budget(text,bigint,jsonb),public.wf_apply_entity_status_without_budget(text,bigint,text),public.wf_apply_entity_status(text,bigint,text),public.wf_entity_data_without_budget(text,bigint),public.wf_entity_data(text,bigint),public.wf_instance_detail(text,bigint),public.wf_notify_level(bigint) from public,anon,authenticated,service_role;
grant execute on function public.pr_access_context(),public.pr_options(),public.pr_invoices(jsonb),public.pr_report(jsonb),public.pr_detail(jsonb),public.pr_save(jsonb),public.pr_transition(jsonb),public.pr_execute(jsonb),public.pr_supports(jsonb),public.pr_support_save(jsonb),public.pr_support_delete(jsonb),public.payment_request_report_options(),public.run_payment_request_report(jsonb),public.wf_act(bigint,text,text,inet),public.wf_instance_detail(text,bigint) to authenticated;
-- Preserve the existing service contract for shared non-request Workflow paths.
grant execute on function public.wf_act(bigint,text,text,inet),public.wf_start_entity_without_budget(text,bigint,jsonb),public.wf_apply_entity_status_without_budget(text,bigint,text),public.wf_apply_entity_status(text,bigint,text),public.wf_entity_data_without_budget(text,bigint),public.wf_entity_data(text,bigint),public.wf_instance_detail(text,bigint),public.wf_notify_level(bigint) to service_role;
notify pgrst,'reload schema';
